import { describe, expect, it, vi } from 'vitest'
import { createSSRApp, h, reactive } from 'vue'
import { renderToString } from 'vue/server-renderer'

// the router needs a mounted page
vi.mock('../router', () => ({ default: { push() {}, resolve: () => ({ href: '/' }) } }))

import DashboardEditActions from './DashboardEditActions.vue'

async function actions(doc: Record<string, any>) {
	const app = createSSRApp({ render: () => h(DashboardEditActions) })
	app.provide('dashboard', reactive({ editing: false, doc: { items: [], ...doc } }))
	// the app registers frappe-ui's Button globally; this stub renders its label
	app.component('Button', {
		props: ['label'],
		render() {
			return h('span', (this as any).label)
		},
	})
	app.config.warnHandler = () => {}
	return renderToString(app)
}

describe('the dashboard builder actions', () => {
	// @feature shared.publish-needs-share
	it('shows Share where the server says the caller may share, and nowhere else', async () => {
		expect(await actions({ read_only: false, can_share: true })).toContain('Share')
		expect(await actions({ read_only: false, can_share: false })).not.toContain('Share')
		expect(await actions({ read_only: false, can_share: false })).toContain('Edit')
	})
})

import frappe

from insights.api.data_sources import (
    get_data_source_table,
    get_data_source_table_columns,
    get_data_source_table_row_count,
)
from insights.tests.base import InsightsIntegrationTestCase

SITE_DB = "Site DB"
USER_A = "row-perm-a@example.com"
USER_B = "row-perm-b@example.com"


def create_user(email):
    if frappe.db.exists("User", email):
        return
    user = frappe.new_doc("User")
    user.email = email
    user.first_name = email.split("@")[0]
    user.send_welcome_email = 0
    user.append("roles", {"role": "Insights User"})
    user.insert(ignore_permissions=True)


class TestSiteDBRowPermissions(InsightsIntegrationTestCase):
    """Data source exploration must not show rows the user cannot read.

    `ToDo` has a `permission_query_conditions` hook in frappe, so it stands in for
    any doctype whose rows are restricted per user.
    """

    @classmethod
    def before_class(cls):
        create_user(USER_A)
        create_user(USER_B)

        cls.todos = {}
        for user, count in ((USER_A, 2), (USER_B, 3)):
            cls.todos[user] = [
                frappe.get_doc(
                    {
                        "doctype": "ToDo",
                        "description": f"row perm test for {user} #{i}",
                        "allocated_to": user,
                    }
                )
                .insert(ignore_permissions=True)
                .name
                for i in range(count)
            ]

    @classmethod
    def after_class(cls):
        for names in cls.todos.values():
            for name in names:
                frappe.delete_doc("ToDo", name, force=True, ignore_permissions=True)
        for email in (USER_A, USER_B):
            frappe.delete_doc("User", email, force=True, ignore_permissions=True)

    def permitted_count(self, user):
        with self.as_user(user):
            return len(frappe.get_list("ToDo", limit_page_length=0))

    # @feature data-source.table-preview
    def test_row_count_matches_permitted_rows(self):
        for user in (USER_A, USER_B):
            with self.as_user(user):
                self.assertEqual(
                    get_data_source_table_row_count(SITE_DB, "tabToDo"),
                    self.permitted_count(user),
                )

    # @feature data-source.table-preview permissions.site-user-permissions
    def test_preview_shows_only_permitted_rows(self):
        for user in (USER_A, USER_B):
            with self.as_user(user):
                rows = get_data_source_table(SITE_DB, "tabToDo")["rows"]
                allowed = set(frappe.get_list("ToDo", pluck="name", limit_page_length=0))
                self.assertEqual({row["name"] for row in rows}, allowed)

    # @feature data-source.table-preview
    def test_column_list_survives_permission_filtering(self):
        # the row filter is a semi-join, so it must not drop columns from the preview
        with self.as_user(USER_A):
            columns = get_data_source_table_columns(SITE_DB, "tabToDo")

        self.assertTrue(any(column.column == "description" for column in columns))

import { describe, expect, it, vi } from 'vitest'
import { createSSRApp, h, reactive } from 'vue'
import { renderToString } from 'vue/server-renderer'
import ChartBuilderActions from './ChartBuilderActions.vue'

// Duplicate uses the router, which needs a mounted page
vi.mock('../../workbook/workbook_items', () => ({ duplicateWorkbookItem: () => {} }))
vi.mock('frappe-ui', async (original) => ({
	...(await original<typeof import('frappe-ui')>()),
	Dropdown: {
		props: ['options'],
		render() {
			return h('span', (this as any).options.map((option: any) => option.label).join('|'))
		},
	},
}))

// For a caller who may not write the chart, the server returns the View's
// result, which has no SQL.

async function menu(executedSQL: string, doc: Record<string, any> = {}) {
	const app = createSSRApp({
		render: () =>
			h(ChartBuilderActions, {
				chart: reactive({ doc: { read_only: !executedSQL, ...doc } }),
				preview: reactive({ result: { executedSQL } }) as any,
				chartEl: null,
				onDownload: () => {},
				onShare: () => {},
			}),
	})
	// The app registers frappe-ui components globally. This test does not, so it
	// silences the warnings for unresolved components.
	app.config.warnHandler = () => {}
	return renderToString(app)
}

describe('the builder card menu', () => {
	// @feature charts.view-sql permissions.viewer-cannot-edit
	it('shows the SQL only where the server sent it', async () => {
		expect(await menu('select 1')).toContain('View SQL')
		expect(await menu('')).not.toContain('View SQL')
	})

	// @feature shared.publish-needs-share
	it('shows Share where the server says the caller may share, and nowhere else', async () => {
		expect(await menu('select 1', { can_share: true })).toContain('Share Chart')
		expect(await menu('select 1', { can_share: false })).not.toContain('Share Chart')
	})
})

import { expect, test } from '../fixtures'
import { INSIGHTS_PATH, VIEWER_EMAIL } from '../helpers/auth'
import {
	createWorkbook,
	deleteTeam,
	deleteWorkbook,
	shareWorkbook,
	uniqueTitle,
} from '../helpers/insights'

test.describe('permissions', () => {
	// @feature permissions.viewer-sees-granted workbook.list
	test('a viewer sees only the workbooks granted to them', async ({ adminApi, viewerPage }) => {
		// Both titles share one marker, so the list search reaches this pair and
		// nothing else. Other agents seed workbooks into the same site, so a count
		// over the whole list would prove nothing.
		const marker = uniqueTitle('Visibility')
		const granted = await createWorkbook(adminApi, `${marker} granted`)
		const hidden = await createWorkbook(adminApi, `${marker} hidden`)
		await shareWorkbook(adminApi, granted.name, [{ user: VIEWER_EMAIL, access: 'view' }])

		await viewerPage.goto(`${INSIGHTS_PATH}/workbook`)
		await viewerPage.getByPlaceholder('Title', { exact: true }).fill(marker)

		await expect(viewerPage.getByText(granted.title)).toBeVisible()
		await expect(viewerPage.getByText(hidden.title)).toHaveCount(0)

		await deleteWorkbook(adminApi, granted.name)
		await deleteWorkbook(adminApi, hidden.name)
	})

	// @feature permissions.viewer-cannot-edit workbook.read-only-shield
	test('a viewer cannot edit a workbook they can read', async ({
		adminApi,
		demoDataSource,
		viewerPage,
		workbookWithQuery,
	}) => {
		const { workbook, query } = workbookWithQuery
		await shareWorkbook(adminApi, workbook.name, [{ user: VIEWER_EMAIL, access: 'view' }])

		await viewerPage.goto(`${INSIGHTS_PATH}/workbook/${workbook.name}/query/${query.name}`)
		await expect(viewerPage.getByRole('link', { name: query.title })).toBeVisible()

		// locator: the read-only marker is a bare lucide icon in the navbar. It
		// has no role, no label and no text, so the class lucide stamps on
		// every icon it renders is the only name this element has.
		const readOnlyMarker = viewerPage.locator('.lucide-shield-alert')
		await expect(readOnlyMarker).toBeVisible()
		await readOnlyMarker.hover()
		// The bubble is rendered twice: the copy a reader sees, and an aria-hidden
		// mirror that names the trigger for a screen reader. The visible one comes
		// first, and neither has a role that tells them apart.
		await expect(
			viewerPage.getByText('You have read-only access to this workbook').first(),
		).toBeVisible()

		// Sharing belongs to the owner, so a granted reader gets no Share button.
		await expect(viewerPage.getByRole('button', { name: 'Share' })).toHaveCount(0)
	})

	// @feature permissions.team-grant
	test('an admin creates a team and grants a resource', async ({
		page,
		adminApi,
		demoDataSource,
	}) => {
		const teamName = uniqueTitle('Team')
		await page.goto(`${INSIGHTS_PATH}/workbook`)

		// The sidebar entries and the settings tabs are divs holding their label,
		// not buttons, so the text is the first level of the ladder that reaches
		// them. Each name is unique until its own panel renders the same heading.
		await page.getByText('Settings', { exact: true }).click()
		await page.getByText('Permissions', { exact: true }).click()

		await page.getByRole('button', { name: 'New Team' }).click()
		await page.getByLabel('Team Name').fill(teamName)
		await page.getByRole('button', { name: 'Create' }).click()
		await expect(page.getByText(teamName)).toBeVisible()

		await page.getByText(teamName).click()
		// The tabs inside the dialog are a frappe-ui TabButtons, which renders a
		// radio group and not buttons.
		await page.getByRole('radio', { name: 'Access' }).click()

		// locator: a resource row has no role, and its Data Source title appears
		// elsewhere on the page. `data-source` names one row exactly. A row holds
		// one checkbox while it stays collapsed.
		const demoRow = page.locator(`[data-source="${demoDataSource}"]`)
		await demoRow.getByRole('checkbox').check()
		await page.getByRole('button', { name: 'Done' }).click()
		await expect(page.getByText('Team updated')).toBeVisible()

		// Reopen the team. A grant that survives a reload is a grant that saved.
		await page.getByText(teamName).click()
		await page.getByRole('radio', { name: 'Access' }).click()
		await expect(demoRow.getByRole('checkbox')).toBeChecked()

		await deleteTeam(adminApi, teamName)
	})

	// @feature permissions.no-source-access-no-query
	test('a user without data source access cannot query it', async ({
		adminApi,
		demoDataSource,
		viewerPage,
		workbook,
	}) => {
		await shareWorkbook(adminApi, workbook.name, [{ user: VIEWER_EMAIL, access: 'edit' }])

		// Team permissions are on for the whole run, and the viewer belongs to no
		// team. The setup project sets the switch, because a test that flipped it
		// would flip it for every worker beside it.
		await viewerPage.goto(`${INSIGHTS_PATH}/workbook/${workbook.name}`)

		// The three interface cards are clickable divs with no role and no
		// label, so getByText is the first level that reaches them.
		await viewerPage.getByText('Query Builder').click()

		await expect(viewerPage.getByText('Pick Starting Data')).toBeVisible()
		await expect(
			viewerPage.getByRole('button', { name: `orders ${demoDataSource}` }),
		).toHaveCount(0)
		await expect(viewerPage.getByRole('button', { name: 'Confirm' })).toBeDisabled()
	})
})
